# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: AI spend across every machine and app tracing to the Logfire project (chat,
#          inline chats, evals): Logfire's query API over the model-request spans
#          pydantic-ai records, each with its cost. Needs the Pydantic API key
#          (full access, the one the Gateway uses; `ds settings sync`); nothing is stored.
# Usage: ai_spend(days=30) gives hourly and top (polars
#        DataFrames), project_name and project_url.
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
from dataclasses import dataclass

import polars as pl
from logfire.query_client import LogfireQueryClient

from ds.settings import get_settings
from ds.util.logging import log_call

__all__ = ["AiSpend", "LogfireKeyMissingError", "ai_spend"]

TOP_REQUESTS = 8

# ds::external-source: checked 2026-11-16 https://pydantic.dev/docs/logfire/reference/sql/
#   taken from it: the `records` table (start_timestamp, trace_id, attributes), `->>` on
#   attributes, DataFusion with PostgreSQL syntax (date_trunc, `::` casts)
# ds::external-source: checked 2026-11-16 https://pydantic.dev/docs/logfire/manage/query-api/
#   taken from it: LogfireQueryClient(read_token=...), query_json_rows (min_timestamp
#   required), its 10,000 row cap
# Attribute names are pydantic-ai's (pydantic_ai._instrumentation.response_attributes):
# every model request is a span with gen_ai.operation.name 'chat', its usage, its model,
# the agent's name (from baggage) and operation.cost (the Gateway-reported cost, else
# genai-prices'; absent when unpriced). Agent run spans carry the run's totals too, so
# only 'chat' spans are summed (else every request would count twice).
_FIELDS = """
    coalesce(attributes->>'gen_ai.agent.name', '') AS agent,
    coalesce(attributes->>'gen_ai.response.model', attributes->>'gen_ai.request.model', '') AS model"""
_WHERE = "attributes->>'gen_ai.operation.name' = 'chat'"

_HOURLY_SQL = f"""
SELECT date_trunc('hour', start_timestamp) AS hour,{_FIELDS},
    count(*) AS requests,
    count(attributes->>'operation.cost') AS priced,
    sum((attributes->>'gen_ai.usage.input_tokens')::bigint) AS input_tokens,
    sum((attributes->>'gen_ai.usage.output_tokens')::bigint) AS output_tokens,
    sum((attributes->>'operation.cost')::double) AS cost
FROM records
WHERE {_WHERE}
GROUP BY 1, 2, 3
"""

_TOP_SQL = f"""
SELECT start_timestamp, trace_id,{_FIELDS},
    (attributes->>'gen_ai.usage.input_tokens')::bigint AS input_tokens,
    (attributes->>'gen_ai.usage.output_tokens')::bigint AS output_tokens,
    (attributes->>'operation.cost')::double AS cost
FROM records
WHERE {_WHERE} AND attributes->>'operation.cost' IS NOT NULL
ORDER BY cost DESC
LIMIT {TOP_REQUESTS}
"""


class LogfireKeyMissingError(RuntimeError):
    """No Pydantic API key is stored (`ds settings sync` asks for it)."""


@dataclass
class AiSpend:
    """Model requests over a time window, from Logfire."""

    hourly: pl.DataFrame
    """One row per hour (UTC `hour`), agent and model: requests, priced (requests with a cost),
    input_tokens, output_tokens, cost (US dollars, priced requests only)."""
    top: pl.DataFrame
    """The most expensive requests: start_at (UTC), trace_id, agent, model, input_tokens,
    output_tokens, cost."""
    project_url: str
    """The Logfire project's web page (its Live view takes a trace_id query)."""
    project_name: str
    """The project the traces are in (its spending limits: ds.data.raw.gateway)."""
    since: dt.datetime


def _frame(result: dict, schema: dict[str, pl.DataType]) -> pl.DataFrame:
    rows = result.get("rows") or []
    frame = pl.DataFrame(rows, schema=list(schema), orient="row") if rows else pl.DataFrame(schema=schema)
    return frame.with_columns(_cast(frame, name, dtype) for name, dtype in schema.items() if name in frame.columns)


def _cast(frame: pl.DataFrame, name: str, dtype: pl.DataType) -> pl.Expr:
    """The column as `dtype`. Timestamps come back as ISO text ("2026-11-14T22:00:00Z"),
    which a plain cast refuses, so those are parsed.
    """
    if isinstance(dtype, pl.Datetime) and frame.schema[name] == pl.String:
        return pl.col(name).str.to_datetime(time_unit=dtype.time_unit, time_zone=dtype.time_zone)
    return pl.col(name).cast(dtype)


def ai_spend(days: int = 30) -> AiSpend:
    """AI spend of the last `days` days, by hour, agent and model, plus the priciest requests.

    Raises LogfireKeyMissingError without the Pydantic API key, and the query client's errors
    (eg a 429 when the plan's query budget is used up) as they are.
    """
    # the one full-access key: the query API takes it as its read token
    token = get_settings().pydantic_gateway_api_key
    if token is None:
        raise LogfireKeyMissingError("No Pydantic API key: run `ds settings sync`.")
    since = dt.datetime.now(dt.UTC) - dt.timedelta(days=days)
    # one 'http' record per request (the app's debug log), as the other sources log theirs
    with LogfireQueryClient(read_token=token.get_secret_value()) as client:
        with log_call("http", "logfire", name=f"ai_spend hourly, {days} days") as call:
            hourly = client.query_json_rows(_HOURLY_SQL, min_timestamp=since, limit=10_000)
            call["rows"] = len(hourly.get("rows") or [])
        with log_call("http", "logfire", name=f"ai_spend top {TOP_REQUESTS}") as call:
            top = client.query_json_rows(_TOP_SQL, min_timestamp=since, limit=TOP_REQUESTS)
            call["rows"] = len(top.get("rows") or [])
        with log_call("http", "logfire", name="project info"):
            info = client.info()
        base_url = str(client.client.base_url).rstrip("/")
    utc = pl.Datetime("us", "UTC")
    counts = {name: pl.Int64 for name in ("requests", "priced", "input_tokens", "output_tokens")}
    hourly_schema = {"hour": utc, "agent": pl.String, "model": pl.String, **counts, "cost": pl.Float64}
    top_schema = {
        "start_timestamp": utc,
        "trace_id": pl.String,
        "agent": pl.String,
        "model": pl.String,
        "input_tokens": pl.Int64,
        "output_tokens": pl.Int64,
        "cost": pl.Float64,
    }
    return AiSpend(
        hourly=_frame(hourly, hourly_schema).with_columns(pl.col(*counts).fill_null(0)),
        top=_frame(top, top_schema).rename({"start_timestamp": "start_at"}),
        project_url=f"{base_url}/{info.get('organization_name', '')}/{info.get('project_name', '')}",
        project_name=info.get("project_name", ""),
        since=since,
    )
